        a, b = 0, 1
        for i in range(2, n + 1):
            a, b = b, a + b
        return b

def max_subarray_sum(nums):
    if not nums:
        return 0

    current_max = nums[0]
    global_max = nums[0]

    for i in range(1, len(nums)):
        current_max = max(nums[i], current_max + nums[i])
        global_max = max(global_max, current_max)

    return global_max

