def roman_to_int(s: str) -> int:
    rom_val = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    sub_pairs = (('IV', 2), ('IX', 2), ('XL', 20), ('XC', 20), ('CD', 200), ('CM', 200))

    s = s.upper()
    total = 0
    i = 0

    while i < len(s):
        if i + 1 < len(s) and (s[i:i+2] in sub_pairs):
            total += rom_val[s[i+1]] - rom_val[s[i]]
            i += 1
        else:
            total += rom_val[s[i]]
        i += 1

    return total

def is_valid_parens(s: str) -> bool:
    """
    Checks if a string of parentheses is valid.
    A string of parentheses is considered valid if each opening parenthesis '(',
    '{', '[' has a corresponding closing parenthesis ')', '}', ']'.
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False

